@extends('layouts.app') @section('title','Dead Stock') @section('content')<h1 class="font-serif text-3xl text-ink">No-sale / dead stock</h1><p class="mb-5 text-sm text-slate-500">Products with no completed sale inside the selected period.</p>@include('reports._nav')<form class="mb-4 flex items-end gap-2"><div><label>No sale for</label><select name="days"><option value="30">30 days</option><option value="60">60 days</option><option value="90" @selected($days===90)>90 days</option><option value="180">6 months</option><option value="365">12 months</option></select></div><button class="btn-primary">Apply</button></form><div class="card overflow-x-auto"><table><thead><tr><th>Product</th><th>Category</th><th>Current stock</th><th>Stock cost value</th><th>Selling price</th><th>Last sale</th><th>Classification</th></tr></thead><tbody>@forelse($products as $p)@php $stock=$p->balances->sum('quantity'); @endphp<tr><td><div class="font-semibold">{{ $p->name }}</div><div class="text-xs text-slate-400">{{ $p->sku }}</div></td><td>{{ $p->category?->name }}</td><td>{{ number_format($stock,4) }} {{ $p->baseUnit->symbol }}</td><td>Rs. {{ number_format($stock*$p->average_cost,2) }}</td><td>Rs. {{ number_format($p->productUnits->first()?->main_selling_price??0,2) }}</td><td>{{ $p->last_sale_at?\Carbon\Carbon::parse($p->last_sale_at)->format('d M Y'):'Never' }}</td><td><span class="badge bg-red-50 text-red-700">Dead stock</span></td></tr>@empty<tr><td colspan="7" class="py-12 text-center text-slate-400">No products meet this rule.</td></tr>@endforelse</tbody></table></div>@endsection
